// Compact binary road graph: encode (Node build) / decode (browser + Node). See web/CONTRACT.md section 2.
//
// Layout (little-endian):
//   "RGRF" | u32 version | u32 headerBytes | u32 reserved | header JSON (UTF-8, padded to 8) | sections, each 8-byte aligned
// header = { meta, nNodes, nChains, nAtoms, nCoords, sections: [{ name, type, length, offset }] }
// Coordinates are int32 microdegrees: nodes absolute; chain polylines delta-encoded within each chain
// (first vertex absolute). Files are gzipped (.graph.bin.gz).

const MAGIC = 0x46524752; // "RGRF" read as little-endian u32
const VERSION = 1;
const TYPES = { i32: Int32Array, f32: Float32Array, u8: Uint8Array, u16: Uint16Array };
const typeName = (a) => Object.keys(TYPES).find((k) => a instanceof TYPES[k]);
const pad8 = (n) => (n + 7) & ~7;

// g: { meta, nodeLon, nodeLat (Float64Array degrees), chainA, chainB, atomStart, atomLen, atomRc, atomRw, atomGrade,
//      atomTunnelRun, atomFlags, atomStrava, coordStart, coordLon, coordLat (Float64Array degrees),
//      optional atomZ0 / atomZ1 (Float32Array metres: elevation at each atom's start / end, in chain direction) }
// Elevations are stored as u16 decimetres offset by +100 m (range -100 .. 6453 m); files without them still decode.
// Optional traffic sections (web/src/traffic.mjs), all Uint8Array(nAtoms):
//   atomAttr    bits 0-1 width level (0 <5.5 m, 1 5.5-13, 2 >=13 m / >=4 lanes, 3 >=19.5 m / median), bit 2 1-digit national
//   atomTraffic estimated vehicles/day, code = round(40*log10 V) - 40  ->  V = 10^((code + 40) / 40)   (0 = none)
//   atomTruck   large-vehicle share in %
//   atomBike    bike facility along the road: 0 none, 1 painted lane, 2 dedicated cycleway, 3 shared sidewalk/path (OSM)
export function encodeGraph(g) {
  const nNodes = g.nodeLon.length, nChains = g.chainA.length, nAtoms = g.atomLen.length, nCoords = g.coordLon.length;
  const micro = (v) => Math.round(v * 1e6);
  const nodeLon = Int32Array.from(g.nodeLon, micro), nodeLat = Int32Array.from(g.nodeLat, micro);
  const dLon = new Int32Array(nCoords), dLat = new Int32Array(nCoords);
  for (let c = 0; c < nChains; c++) {
    let px = 0, py = 0;
    for (let i = g.coordStart[c]; i < g.coordStart[c + 1]; i++) {
      const x = micro(g.coordLon[i]), y = micro(g.coordLat[i]);
      dLon[i] = i === g.coordStart[c] ? x : x - px; dLat[i] = i === g.coordStart[c] ? y : y - py;
      px = x; py = y;
    }
  }
  const arrays = {
    nodeLon, nodeLat, chainA: g.chainA, chainB: g.chainB, atomStart: g.atomStart,
    atomLen: g.atomLen, atomRc: g.atomRc, atomRw: g.atomRw, atomGrade: g.atomGrade, atomTunnelRun: g.atomTunnelRun,
    atomFlags: g.atomFlags, atomStrava: g.atomStrava, coordStart: g.coordStart, coordDLon: dLon, coordDLat: dLat,
  };
  const zEnc = (v) => Math.max(0, Math.min(65535, Math.round((v + 100) * 10)));
  if (g.atomZ0 && g.atomZ1) { arrays.atomZ0 = Uint16Array.from(g.atomZ0, zEnc); arrays.atomZ1 = Uint16Array.from(g.atomZ1, zEnc); }
  for (const k of ['atomAttr', 'atomTraffic', 'atomTruck', 'atomBike']) if (g[k]) arrays[k] = g[k];
  const sections = [];
  let off = 0;
  for (const [name, a] of Object.entries(arrays)) {
    const type = typeName(a);
    if (!type) throw new Error(`unsupported array type for ${name}`);
    sections.push({ name, type, length: a.length, offset: off });
    off = pad8(off + a.byteLength);
  }
  const header = new TextEncoder().encode(JSON.stringify({ meta: g.meta, nNodes, nChains, nAtoms, nCoords, sections }));
  const headerBytes = pad8(header.length);
  const start = 16 + headerBytes;
  const out = new Uint8Array(start + off);
  const dv = new DataView(out.buffer);
  dv.setUint32(0, MAGIC, true); dv.setUint32(4, VERSION, true); dv.setUint32(8, headerBytes, true);
  out.set(header, 16);
  out.fill(0x20, 16 + header.length, start); // pad header with spaces (still valid JSON)
  for (const s of sections) {
    const a = arrays[s.name];
    out.set(new Uint8Array(a.buffer, a.byteOffset, a.byteLength), start + s.offset);
  }
  return out;
}

// buf: ArrayBuffer or Uint8Array of the *uncompressed* graph
export function decodeGraph(buf) {
  const u8 = buf instanceof Uint8Array ? buf : new Uint8Array(buf);
  if (u8[0] === 0x1f && u8[1] === 0x8b) throw new Error('decodeGraph: data is gzipped; gunzip first (or use loadGraph)');
  // copy into an 8-aligned buffer so typed views are valid
  const ab = u8.byteOffset % 8 === 0 ? u8.buffer : u8.slice().buffer;
  const base = u8.byteOffset % 8 === 0 ? u8.byteOffset : 0;
  const dv = new DataView(ab, base);
  if (dv.getUint32(0, true) !== MAGIC) throw new Error('decodeGraph: bad magic');
  if (dv.getUint32(4, true) !== VERSION) throw new Error('decodeGraph: unsupported version');
  const headerBytes = dv.getUint32(8, true);
  const header = JSON.parse(new TextDecoder().decode(new Uint8Array(ab, base + 16, headerBytes)));
  const start = base + 16 + headerBytes;
  const A = {};
  for (const s of header.sections) A[s.name] = new TYPES[s.type](ab, start + s.offset, s.length);
  const nodeLon = Float64Array.from(A.nodeLon, (v) => v / 1e6), nodeLat = Float64Array.from(A.nodeLat, (v) => v / 1e6);
  const coordLon = new Float64Array(header.nCoords), coordLat = new Float64Array(header.nCoords);
  for (let c = 0; c < header.nChains; c++) {
    let x = 0, y = 0;
    for (let i = A.coordStart[c]; i < A.coordStart[c + 1]; i++) {
      x = i === A.coordStart[c] ? A.coordDLon[i] : x + A.coordDLon[i];
      y = i === A.coordStart[c] ? A.coordDLat[i] : y + A.coordDLat[i];
      coordLon[i] = x / 1e6; coordLat[i] = y / 1e6;
    }
  }
  return {
    meta: header.meta, nNodes: header.nNodes, nChains: header.nChains, nAtoms: header.nAtoms,
    nodeLon, nodeLat, chainA: A.chainA, chainB: A.chainB, atomStart: A.atomStart,
    atomLen: A.atomLen, atomRc: A.atomRc, atomRw: A.atomRw, atomGrade: A.atomGrade, atomTunnelRun: A.atomTunnelRun,
    atomFlags: A.atomFlags, atomStrava: A.atomStrava, coordStart: A.coordStart, coordLon, coordLat,
    atomZ0: A.atomZ0 ? Float32Array.from(A.atomZ0, (v) => v / 10 - 100) : null,
    atomZ1: A.atomZ1 ? Float32Array.from(A.atomZ1, (v) => v / 10 - 100) : null,
    atomAttr: A.atomAttr ?? null, atomTraffic: A.atomTraffic ?? null, atomTruck: A.atomTruck ?? null, atomBike: A.atomBike ?? null,
  };
}

async function gunzip(ab) {
  const stream = new Blob([ab]).stream().pipeThrough(new DecompressionStream('gzip'));
  return new Response(stream).arrayBuffer();
}

// Browser (and Node 18+): fetch a .graph.bin.gz. Works whether or not the server already decoded the gzip.
export async function loadGraph(url) {
  const res = await fetch(url);
  if (!res.ok) throw new Error(`loadGraph: HTTP ${res.status} for ${url}`);
  let ab = await res.arrayBuffer();
  const head = new Uint8Array(ab, 0, 2);
  if (head[0] === 0x1f && head[1] === 0x8b) ab = await gunzip(ab);
  return decodeGraph(ab);
}

// Fetch a gzipped (or plain) JSON file such as <source>.hazards.geojson.gz.
export async function loadJsonGz(url) {
  const res = await fetch(url);
  if (!res.ok) throw new Error(`loadJsonGz: HTTP ${res.status} for ${url}`);
  let ab = await res.arrayBuffer();
  const head = new Uint8Array(ab, 0, 2);
  if (head[0] === 0x1f && head[1] === 0x8b) ab = await gunzip(ab);
  return JSON.parse(new TextDecoder().decode(ab));
}

export function chainCoords(graph, c) {
  const out = [];
  for (let i = graph.coordStart[c]; i < graph.coordStart[c + 1]; i++) out.push([graph.coordLon[i], graph.coordLat[i]]);
  return out;
}
