// runs of atoms with a bike facility alongside (1 lane, 2 cycleway, 3 shared sidewalk) as lines, by interpolating along chain polylines
function bikeFC(graph) {
  if (state.bikeFC) return state.bikeFC;
  const features = [];
  if (graph.atomBike) for (let c = 0; c < graph.nChains; c++) {
    let any = false; for (let i = graph.atomStart[c]; i < graph.atomStart[c + 1]; i++) if (graph.atomBike[i]) { any = true; break; }
    if (!any) continue;
    const cs = chainCoords(graph, c), kx = Math.cos((cs[0][1] * Math.PI) / 180) * 111320, ky = 110574, cum = [0];
    for (let q = 1; q < cs.length; q++) cum.push(cum[q - 1] + Math.hypot((cs[q][0] - cs[q - 1][0]) * kx, (cs[q][1] - cs[q - 1][1]) * ky));
    let La = 0; for (let i = graph.atomStart[c]; i < graph.atomStart[c + 1]; i++) La += graph.atomLen[i];
    const sc = cum[cum.length - 1] / (La || 1);
    const at = (d) => { let q = 1; while (q < cum.length - 1 && cum[q] < d) q++; const f = cum[q] > cum[q - 1] ? (d - cum[q - 1]) / (cum[q] - cum[q - 1]) : 0; return [cs[q - 1][0] + f * (cs[q][0] - cs[q - 1][0]), cs[q - 1][1] + f * (cs[q][1] - cs[q - 1][1])]; };
    let d = 0, run = null;
    const flush = () => { if (run && run.coords.length > 1) features.push({ type: 'Feature', properties: { bike: run.v }, geometry: { type: 'LineString', coordinates: run.coords } }); run = null; };
    for (let i = graph.atomStart[c]; i < graph.atomStart[c + 1]; i++) {
      const v = graph.atomBike[i], d0 = d * sc, d1 = (d + graph.atomLen[i]) * sc; d += graph.atomLen[i];
      if (!v) { flush(); continue; }
      if (!run || run.v !== v) { flush(); run = { v, coords: [at(d0)] }; }
      for (let q = 0; q < cs.length; q++) if (cum[q] > d0 && cum[q] < d1) run.coords.push(cs[q]);
      run.coords.push(at(d1));
    }
    flush();
  }
  state.bikeFC = { type: 'FeatureCollection', features };
  return state.bikeFC;
}
