    const f = featureAt(e.point);
    if (!f) { map.getCanvas().style.cursor = ''; popup.remove(); return; }
    map.getCanvas().style.cursor = 'pointer';
    popup.setLngLat(e.lngLat).setHTML(infoHtml(f)).addTo(map);
